update public.sarpras_katalog set spesifikasi='{"nama_form": "Kemeja", "default": "Jenis Bahan: OXBC\nWarna/ Kode: Cream\nBordir/Sablon/DTF/Printing: Bordir", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_seragam_kemeja.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_SERAGAM_KEMEJA';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Kaos Polo", "default": "Jenis Bahan: PE Soft Single\nWarna/ Kode: Marun\nBordir/Sablon/DTF/Printing: Bordir\nManset: Manset Kerah & Lengan", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_seragam_kaos_polo.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_SERAGAM_KAOS_POLO';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Pallet", "default": null, "variants": {"Pallet Biru": "Jenis Produk: Pallet plastik heavy duty\nMaterial: HDPE (High Density Polyethylene) / Plastik berkualitas tinggi\nKapasitas Beban Statis: 3.000 kg\nKapasitas Beban Dinamis: 1.000 kg\nUkuran: 1100 x 1100 x 120 mm\nBerat Pallet: 7 kg\nSistem Entry: 4 ways entry (dapat diakses forklift/ hand pallet dari 4 sisi)\nWarna: Biru\nSurface: Anti slip/ permukaan stabil untuk penyimpanan barang\nKetebalan Deck/ Permukaan: 5 – 10 mm\nKetebalan Dinding/ Rib Struktur: 3 – 5 mm", "Pallet Hitam": "Jenis Produk: Pallet plastik heavy duty\nMaterial: HDPE (High Density Polyethylene) / Plastik berkualitas tinggi\nKapasitas Beban Statis: 3.000 kg\nKapasitas Beban Dinamis: 1.000 kg\nUkuran: 1100 x 1100 x 200 mm\nBerat Pallet: 7 kg\nSistem Entry: 4 ways entry (dapat diakses forklift/ hand pallet dari 4 sisi)\nWarna: Hitam\nSurface: Anti slip/ permukaan stabil untuk penyimpanan barang\nKetebalan Deck/ Permukaan: 5 - 10 mm\nKetebalan Dinding/ Rib Struktur: 1 – 5 mm"}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_pallet_pallet_biru.jpg", "./assets/img/sarpras/ops_pallet_pallet_hitam.jpg"]}'::jsonb,daftar_tipe='["Pallet Biru", "Pallet Hitam"]'::jsonb where item_id='OPS_PALLET';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Printer", "default": "Merek / Tipe: Epson LX-310 Dot Matrix Printer\nTeknologi Cetak: Impact Dot Matrix\nJumlah Pin: 9-Pin Narrow Carriage\nKecepatan Cetak: Hingga 357 karakter per detik (cps)\nMode Cetak: Draft, High Speed Draft, Draft Condensed, LQ\nResolusi / Kualitas: Hingga Letter Quality (LQ)\nInterface / Konektivitas: USB, Serial, Parallel\nBuffer Memory: 128 KB\nLebar Cetak: Narrow Carriage\nJenis Kertas: Continuous form, cut sheet, multi-part paper\nUkuran Kertas: A4, continuous form, envelope, dll\nSistem Penarikan Kertas: Tractor feed & manual insertion\nKetahanan (MTBF): Hingga 10.000 jam\nUmur Head Printer: ± 400 juta stroke\nRibbon Cartridge: Fabric Ribbon Cartridge (Black)\nUmur Ribbon: ± 4 juta karakter\nTingkat Kebisingan: ± 53 dB\nKonsumsi Daya: ± 27W (operasi), hemat energi saat standby\nTegangan Listrik: AC 220 – 240 V\nFrekuensi: 50 – 60 Hz\nSistem Operasi: Windows XP / Vista / 7 / 8 / 10 / 11\nDimensi: ± 362 x 275 x 154 mm\nBerat: ± 4,1 kg\nFitur Tambahan: Mendukung multi-copy printing (hingga 4 rangkap), continuous printing\nKegunaan: Cocok untuk administrasi, invoice, dan operasional skala besar", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_printer.jpg", "./assets/img/sarpras/ops_printer_samping.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_PRINTER';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Brankas", "default": null, "variants": {"ET571": "Jenis Produk: Digital Safe Box Tipe ET571\nMaterial: Heavy duty carbon steel/ pelat baja berkualitas tinggi\nDimensi Dalam: Panjang 370 mm, Lebar 310 mm, Tinggi 440 mm\nDimensi Luar: Panjang 380 mm, Lebar 320 mm, Tinggi 450 mm\nTebal Dinding: 1,5 – 2 mm\nTebal Pintu: 4 - 6 mm\nBerat: ± 25 kg\nSistem Penguncian: Key/ Password\nSistem Darurat: Emergency key / manual key\nSurface Treatment: Finishing powder coating / electrostatic powder coating anti karat dan tahan gores\nAksesoris Interior: Terdapat tray penyimpanan dan reset button", "Black 42": "Jenis Produk: Digital Safe Box Tipe Black 42\nMaterial: Heavy duty carbon steel/ pelat baja berkualitas tinggi\nDimensi Dalam: Panjang 375 mm, Lebar 375 mm, Tinggi 240 mm\nDimensi Luar: Panjang 380 mm, Lebar 325 mm, Tinggi 450 mm\nTebal Dinding: 1,5 – 2 mm\nTebal Pintu: 4 - 6 mm\nBerat: ± 25 kg\nSistem Penguncian: Fingerprint, Password Digital, Kunci Mekanis (Emergency Key)\nSistem Darurat: Emergency key / manual key\nSurface Treatment: Powder Coating anti karat dan ramah lingkungan\nAksesoris Interior: Terdapat tray penyimpanan dan reset button"}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_brankas_black_42.jpg", "./assets/img/sarpras/kmn_brankas_et571.jpg"]}'::jsonb,daftar_tipe='["ET571", "Black 42"]'::jsonb where item_id='KMN_BRANKAS';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Genset", "default": "Jenis: Genset Diesel\nTipe: Non Silent (Open Type) / Silent Type\nKapasitas: 10-20 KVA\nDaya Keluaran: Menyesuaikan kapasitas genset\nFrekuensi: 50 Hz\nTegangan Output: 220V dan/atau 380 V\nFaktor Daya: 0,8\nDimensi: Menyesuaikan kapasitas dan desain pabrikan\nBerat: Menyesuaikan kapasitas dan desain pabrikan\nTingkat Kebisingan: Menyesuaikan tipe genset (Open Type atau Silent Type)\nSistem Pendingin: Pendingin udara (Air Cooled) atau pendingin air (Water Cooled), sesuai kapasitas\nRangka: Rangka baja dengan dudukan anti getar (anti vibration mounting)\nAlternator: Brushless atau setara\nSistem Regulasi Tegangan: Automatic Voltage Regulator (AVR) atau setara\nSistem Proteksi: Dilengkapi proteksi terhadap beban lebih, tekanan oli rendah, temperatur tinggi, dan gangguan operasional lainnya\nFitur Tambahan: Dilengkapi emergency stop, indikator pengoperasian, dan terminal grounding\nPanel Kontrol: Dilengkapi panel kontrol digital atau analog untuk pemantauan dan pengoperasian genset", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_genset.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_GENSET';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Stempel", "default": "Jenis Stempel: Otomatis (Flash Stamp)\nBentuk Gagang & Karet: Persegi Panjang (Rectangular)\nEstimasi Panjang Gagang: 55 mm - 70 mm\nEstimasi Lebar Gagang: 25 mm - 40 mm\nEstimasi Tinggi Stempel: 70 mm - 90 mm\nEstimasi Panjang Karet Teks: 51 mm - 66 mm\nEstimasi Lebar Karet Teks: 22 mm - 36 mm\nBahan Gagang (Handle): Plastik PVC / ABS High Quality\nBahan Dudukan Karet: Plastik Akrilik / Komposit Keras\nJenis Karet: Karet Flash (Flash Foam)\nWarna Tinta Default: Merah\nDaya Tahan Pengecapan: 200 - 500 Kali Cap", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_stempel.jpg", "./assets/img/sarpras/ops_stempel_2.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_STEMPEL';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Struk", "default": "Ukuran: 57 mm - 58 mm\nDiameter Gulungan: 30 mm\nKetebalan Kertas: 58 gsm - 65 gsm", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_struk.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_STRUK';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Thermal Label", "default": "Ukuran: 50 mm x 30 mm\nInti Roll (Core): 1 inci (25 mm) atau kompatibel dengan printer yang digunakan\nJumlah Label per Roll: Minimal 1.000 label/roll\nJenis: Thermal Label Stiker", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_thermal_label.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_THERMAL_LABEL';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Tempat Sampah Besar", "default": null, "variants": {"3 Pilah (Triple Bin)": "Jenis Produk: Tempat Sampah 3 Pilah (Triple Bin) dengan Rangka/ Stand\nJumlah Kompartemen: 3 (tiga) kompartemen untuk pemilahan sampah\nJenis Bahan Tong: High Density Polyethylene (HDPE), Fiberglass, atau material sejenis yang kuat, tahan benturan, tahan cuaca, tahan sinar UV, serta tidak mudah retak\nKapasitas: Minimal 40 Liter s.d. 50 Liter per tong (Total kapasitas 1 set akumulatif minimal 120 - 150 Liter)\nMaterial Rangka: Besi galvanis, baja ringan, hollow steel, atau material logam sejenis dengan lapisan antikarat (powder coating atau galvanis)\nDimensi Tong: Menyesuaikan kapasitas 40–50 Liter\nDimensi Set: Menyesuaikan desain pabrikan, terdiri atas 1 (satu) rangka penyangga dengan 3 (tiga) kompartemen\nWarna: Minimal terdiri dari 3 warna berbeda sesuai kebutuhan pemilahan sampah\nPenutup: Dilengkapi tutup yang menyatu dengan bodi, model ayun (swing), bukaan atas, atau model sejenis\nIdentifikasi: Dilengkapi simbol, label, atau stiker yang menunjukkan jenis pemilahan sampah, serta tersedia area atau media untuk pemasangan logo", "Wheelie Bin": "Jenis Produk: Tempat sampah dengan roda (Wheelie Bin)\nJumlah Produk: 1 (satu) set terdiri atas 3 (tiga) unit tempat sampah dengan roda\nKapasitas: Minimal 120 Liter per unit (total kapasitas 1 set minimal 360 Liter)\nMaterial: High Density Polyethylene (HDPE) atau material sejenis yang kuat, tahan benturan, tahan cuaca, tahan sinar UV, dan tidak mudah retak\nDimensi: Menyesuaikan kapasitas minimal 120 liter\nWarna: Body berwarna merah, dengan warna tutup disesuaikan dengan kebutuhan pemilahan sampah (hijau/biru/kuning/warna lainnya sesuai kebutuhan)\nPenutup: Dilengkapi tutup dengan engsel terintegrasi\nRoda: Minimal 2 roda untuk memudahkan pemindahan\nPegangan: Dilengkapi pegangan yang ergonomis dan menyatu dengan bodi\nIdentifikasi: Dilengkapi simbol, label, atau stiker yang menunjukkan jenis pemilahan sampah, serta tersedia area atau media untuk pemasangan logo"}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_tempat_sampah_3_pilah_triple_bin.jpg", "./assets/img/sarpras/ops_tempat_sampah_3_pilah_triple_bin_belakang.jpg", "./assets/img/sarpras/ops_tempat_sampah_wheelie_bin.jpg", "./assets/img/sarpras/ops_tempat_sampah_wheelie_bin_belakang.jpg", "./assets/img/sarpras/ops_tempat_sampah_wheelie_bin_samping.jpg"]}'::jsonb,daftar_tipe='["3 Pilah (Triple Bin)", "Wheelie Bin"]'::jsonb where item_id='OPS_TEMPAT_SAMPAH';